  const hasCommands = commands !== null && (commands?.getChildren(SEQN_NODES.COMMAND).length > 0 || lgo !== null);
  const hasImmediateCommands = immediateCommands !== null;
  const hasHardwareCommands = hardwareCommands !== null;
