const SatfSasfParser = parser;
function getSatfLRLanguage(resources) {
  return resources.LRLanguage.define({
    languageData: {
      commentTokens: { line: '#' },
    },
    parser: parser.configure({
      props: [
        language.foldNodeProp.add({
          // TODO: Add a custom folder
        }),
        styleTags({
          Activity: tags.strong,
          ActivityTypeCode: tags.namespace,
          ActivityTypeGroup: tags.keyword,
          ActivityTypeName: tags.namespace,
          Assignment: tags.strong,
          Command: tags.strong,
          CommandDynamic: tags.strong,
          CommandsDynamic: tags.strong,
          Comment: tags.comment,
          Data: tags.comment,
          Enum: tags.url,
          Ground: tags.strong,
          HeaderPair: tags.namespace,
          HeaderRecord: tags.comment,
          Keyword: tags.comment,
          LineSeparator: tags.comment,
          Loop: tags.strong,
          Name: tags.strong,
          Note: tags.strong,
          Number: tags.number,
          Parameters: tags.keyword,
          Request: tags.keyword,
          SatfComment: tags.comment,
          SeqTranDirective: tags.keyword,
          SeqTranSet: tags.keyword,
          SeqgenDirective: tags.keyword,
          Stem: tags.keyword,
          StepLabel: tags.number,
          String: tags.string,
          Type: tags.keyword,
          TypeGroup: tags.keyword,
          TypeName: tags.strong,
          Value: tags.namespace,
          Variables: tags.keyword,
        }),
      ],
    }),
  });
}

