  SASF,
  HEADER,
  SFDU_HEADER,
  HEADER_PAIRS,
  HEADER_PAIR,
  KEY,
  VALUE,
  BODY,
  ACTIVITY_TYPE_DEFINITIONS,
  ACTIVITY_TYPE_GROUP,
  ACTIVITY_TYPE_NAME,
  ACTIVITY_TYPE_CODE,
  SEQGEN,
  VIRTUAL_CHANNEL,
  ON_BOARD_FILENAME,
